"""Collect bounded native recovery, individually complete runtime runs and normal Editor handoff."""
from pathlib import Path
import json,hashlib,datetime
R=Path(__file__).resolve().parents[1];Q=R/'reports'
def read(n):return json.loads((Q/n).read_text())
runs=[]
for name in ['stargem-pig-playmode.json','stargem-pig-regression-raid.json','stargem-pig-regression-playtest-issues.json','stargem-pig-regression-raid-helper.json','stargem-pig-regression-startup.json']:
 d=read(name);assert d['status']=='completed' and d['summary']['total']>0 and d['summary']['total']==d['summary']['passed'] and d['summary']['failed']==0,name
 runs.append({'report':'reports/'+name,'duration':d['duration'],'summary':d['summary'],'independentCompleteRun':True})
p=read('stargem-pig-preservation.json');assert p['userMainAndBackupUnchanged'] and p['existingRectTransformsChanged']==0
h=read('stargem-pig-editor-handoff.json');assert h['objects']==35834 and h['missingScripts']==0 and h['starGemPigBound'] and h['starGemPigPageHidden'] and h['starGemHudBound'] and h['starGemNativeAlertIsNull'] and h['persist']
assert not h['playing'] and not h['dirty'] and not h['compiling'] and not h['updating'] and not h['saveFolderOverride'] and not h['testHostFolder'] and h['inputOverrides']==h['mouseFixtures']==0
c=read('stargem-pig-final-console-status.json')['data']['result']['groundTruth'];assert not c['compilationFailed'] and not c['compiling'] and c['consoleErrors']==0
visual=[]
for suffix in ['locked-page','full-page','level-two','sold-out']:
 f=Q/'visual'/f'stargem-pig-{suffix}-gpu.png';assert f.exists();visual.append({'path':str(f.relative_to(R)),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'actuallyViewed':True})
native=read('stargem-pig-native-contract.json');assert len(native['methods'])==48 and native['businessMethods']==42 and native['exceptionHelpers']==6 and native['allQueriesCompleted']
out={'updatedUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'target':'com.Chodun.CatGunner 1.1.61 vc257','rule':48,'editor':'6000.4.10f1','native':native,'connected':['original raid HUD -> original StarGem pig page and close','native Game_Start +50 and Boss_Destroyed +25 -> shared original save state','capacity 660/1500/2500, purchase limits 2/2/1 -> tier promotion and sold out','original cash button -> authorized asynchronous payment simulation -> star wallet, UI and archive','local weekly observer -> reset and reject pending previous tier','independent cold reload -> unclaimed amount, count, level and simulation ledger'],'adapters':['user-authorized local payment success/cancel/disabled simulator; no money charged or production receipts','native fallback prices; live store prices unavailable','shared local calendar provider with quarter-second observer and mirrored UI reconciliation; trusted Time_manager services absent','explicit Unity object null guard for original Alert_obj=0','long intermediate for malformed local save addition; existing decimal/combat adapters','Editor transient layout tracker restoration preserves existing original rects'],'independentTests':runs,'historicalAttempts':['reports/stargem-pig-before-failure.json','reports/stargem-pig-null-reference-failure.json'],'projectileObservation':read('stargem-pig-projectile-observation.json'),'gpu':visual,'preservation':p,'handoff':h,'finalConsole':c,'realPaymentCharged':False,'realReceiptOrStoreTransactionHistoryForged':False,'userProgressRestoredOrReset':False,'apkBuilt':False,'deviceAcceptance':False,'gitCommitOrPush':False,'scopeComplete':False,'pending':'SpriteSkin component149337, advanced energy/mesh VFX and full skeletal deformation; remove-ads automatic rewards/sweeps; trusted timing; remaining I2/UI/buff/ad-rebirth/temp-gun/service workflows; two unbound tutorial HUDs; Player/device acceptance'}
(Q/'stargem-pig-evidence.json').write_text(json.dumps(out,ensure_ascii=False,indent=2));print({'tests':[r['summary'] for r in runs],'objects':h['objects'],'userProgressUnchanged':True,'scopeComplete':False})
